SOURCE_INPUTS={'caster': {'bytes': 30695, 'sha256': '80897e3375ba44d1dea66a693fe3ba0ac5cf41d62a533fd5dc814f1b1c2740d9', 'compressed': ''}, 'press': {'bytes': 15690, 'sha256': 'd4203e107df6d462fc197c921e48b6df1b120e435896772d3e461a169c17c3c3', 'compressed': ''}}
